<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useSimulator } from '../../state/simulator'
import { autoSettingItems, faultKinds } from '../../data/tools'
import { deviceView, kindLabel, deviceStatus, numberValue, locateDevice, openDevice, downloadCsv, clone } from './toolHelpers'
import { injectConfiguredFault, resetConfiguredFault, type FaultType } from './faultActions'
import ToolTable from './ToolTable.vue'
import DeviceVisual from './DeviceVisual.vue'

const { state, ensureDevice, setDevice, notify, record, downloadJson } = useSimulator()
const search = ref('')
const kindFilter = ref('全部')
const selectedId = ref(String(state.modal?.payload?.id || ''))
const faultType = ref<FaultType>('failure')
const forcedValue = ref(0)
const message = ref('')
const frozen = ref(false)
const confirmation = ref(false)
const settingsDraft = reactive<Record<string,boolean>>(Object.fromEntries(autoSettingItems.map(item => [item.key,state.settings[item.key] !== false])))
const activeTab = ref('设备异常')
const allDevices = computed(() => [...new Map(Object.values(state.devices).map(device => [device.id,deviceView(device.id)])).values()].sort((a,b) => a.id.localeCompare(b.id,'zh-CN',{numeric:true})))
const filtered = computed(() => allDevices.value.filter(device => (kindFilter.value === '全部' || device.kind === kindFilter.value) && (!search.value || `${device.id} ${device.name}`.toLowerCase().includes(search.value.toLowerCase()))))
const device = computed(() => deviceView(selectedId.value || filtered.value[0]?.id || 'P101'))
const isSensor = computed(() => ['sensor','gauge','digital-gauge'].includes(device.value.kind))
const availableFaults = computed(() => faultKinds.filter(fault => fault.id === 'failure' || fault.id === 'disabled' || (fault.id === 'stuck' && device.value.kind === 'valve') || (['freeze','bias'].includes(fault.id) && isSensor.value) || (fault.id === 'leak' && ['tank','hose','pipe','valve','pump','station'].includes(device.value.kind))))
watch(() => device.value.id, () => { forcedValue.value=device.value.value;message.value='';frozen.value=Boolean(device.value.frozen);faultType.value='failure' },{immediate:true})
const activeFaults = computed(() => allDevices.value.filter(device => device.error || !device.enabled || device.frozen || device.leaking).map(device => ({...device,faultType:String(device.faultType || ''),status:deviceStatus(device),description:String(device.faultMessage || faultKinds.find(fault => fault.id === device.faultType)?.name || deviceStatus(device)),time:String(device.faultTime || '本地状态')})))
const faultColumns = [{key:'id',label:'设备编号'},{key:'name',label:'名称'},{key:'description',label:'异常内容'},{key:'value',label:'当前值',numeric:true},{key:'time',label:'注入时间'},{key:'actions',label:'操作',sortable:false}]
function inject() {
  if (!Number.isFinite(Number(forcedValue.value))) return notify('异常数值必须是有限数字。','warning')
  if (['freeze','stuck'].includes(faultType.value) && (forcedValue.value < (faultType.value === 'stuck' ? 0 : device.value.min) || forcedValue.value > (faultType.value === 'stuck' ? 100 : device.value.max))) return notify('指定异常数值超出该设备量程。','warning')
  injectConfiguredFault(device.value.id,faultType.value,Number(forcedValue.value),message.value)
}
function submitSensorValue() {
  if (!Number.isFinite(Number(forcedValue.value)) || forcedValue.value < device.value.min || forcedValue.value > device.value.max) return notify(`数值须为 ${device.value.min}～${device.value.max} ${device.value.unit}。`,'warning')
  const current=ensureDevice(device.value.id,'sensor',device.value.name)
  if (!setDevice(current.id,{enabled:true,value:Number(forcedValue.value),frozen:frozen.value})) return
  record(`异常配置强制提交传感器值 ${forcedValue.value} ${device.value.unit}，${frozen.value ? '关闭更新' : '允许更新'}`,current.id)
  notify('传感器值和更新状态已提交。','success')
}
function resetAll() {
  const faults=activeFaults.value.map(fault => fault.id)
  for (const id of faults) resetConfiguredFault(id)
  confirmation.value=false
  record(`复位全部 ${faults.length} 个设备异常`)
  notify(`已复位 ${faults.length} 个设备，动力设备保持停止。`,'success')
}
function scenario(name:string) {
  if (name==='供应泵双故障') {injectConfiguredFault('P101','failure',0,'1号燃料供应泵运行异常');injectConfiguredFault('P102','failure',0,'2号燃料供应泵运行异常')}
  if (name==='氮气主风机故障') injectConfiguredFault('FanForPit7AMaster','failure',0,'氮气间主风机异常')
  if (name==='燃料准备间泄漏') injectConfiguredFault('Di41','freeze',40,'燃料准备间可燃气体高高：40%LEL')
}
function saveAutoSettings() {for(const item of autoSettingItems)state.settings[item.key]=settingsDraft[item.key];record('保存异常自动触发配置');notify('异常自动触发设置已保存到本地。','success')}
function exportFaults() {downloadCsv('设备异常配置.csv',['编号','名称','异常类型','内容','当前值','单位','注入时间'],activeFaults.value.map(fault => [fault.id,fault.name,fault.faultType,fault.description,fault.value,fault.unit,fault.time]));record('导出设备异常 CSV')}
</script>

<template>
  <div class="fault-dialog"><div class="fault-heading"><div><h3>异常配置与故障注入</h3><p>设备故障、传感器强制值、阀门操作锁定及本地复位</p></div><span class="badge fault-count">{{ activeFaults.length }} 个异常设备</span></div><nav class="tabs fault-tabs"><button v-for="tab in ['设备异常','自动触发设置','当前异常列表']" :key="tab" class="tab" :class="{active:activeTab===tab}" type="button" @click="activeTab=tab">{{ tab }}</button></nav><template v-if="activeTab === '设备异常'"><div class="scenario-toolbar"><span>常用异常工况</span><button v-for="name in ['供应泵双故障','氮气主风机故障','燃料准备间泄漏']" :key="name" class="btn" type="button" @click="scenario(name)">{{ name }}</button></div><div class="fault-layout"><aside class="device-list card"><div class="list-search"><input v-model="search" class="field" placeholder="输入设备 ID / 名称以搜索"><select v-model="kindFilter" class="field" aria-label="故障设备类型"><option>全部</option><option v-for="kind in [...new Set(allDevices.map(device => device.kind))]" :key="kind" :value="kind">{{ kindLabel(kind) }}</option></select></div><div class="device-list-scroll"><button v-for="item in filtered" :key="item.id" class="device-option" :class="{selected:device.id===item.id,faulty:item.error || !item.enabled}" type="button" @click="selectedId=item.id"><div><strong>{{ item.id }}</strong><span>{{ item.name }}</span></div><span class="option-status">{{ item.error ? '异常' : !item.enabled ? '锁定' : kindLabel(item.kind) }}</span></button><div v-if="!filtered.length" class="empty-state">没有匹配设备。</div></div><small class="list-count">筛选 {{ filtered.length }} / {{ allDevices.length }} 个设备</small></aside><section class="fault-editor card"><div class="selected-device"><DeviceVisual :kind="device.kind" :value="device.value" :working="device.working" :error="device.error" :sensor-type="String(device.sensorType||'')"/><div><strong>{{ device.id }}</strong><h4>{{ device.name }}</h4><span class="badge">{{ deviceStatus(device) }}</span><p>{{ device.value.toFixed(2) }} {{ device.unit }}</p></div></div><div class="editor-actions"><button class="btn" type="button" @click="locateDevice(device.id)">高亮查看</button><button class="btn" type="button" @click="openDevice(device.id,device.kind)">设备操作</button><button class="btn btn-success" type="button" @click="resetConfiguredFault(device.id)">设备故障复位</button></div><div v-if="isSensor" class="sensor-override"><h4>传感器系统值更新</h4><label class="check-option"><input v-model="frozen" type="checkbox">是否关闭更新（冻结自动值）</label><div class="override-row"><label>输入值（{{ device.unit }}）<input v-model.number="forcedValue" class="field" type="number" step="any" :min="device.min" :max="device.max"></label><button class="btn btn-primary" type="button" @click="submitSensorValue">提交传感器值更新</button></div></div><h4>故障注入</h4><label>异常类型<select v-model="faultType" class="field"><option v-for="fault in availableFaults" :key="fault.id" :value="fault.id">{{ fault.name }}</option></select></label><p class="fault-description">{{ faultKinds.find(fault => fault.id===faultType)?.description }}</p><label v-if="['stuck','freeze','bias'].includes(faultType)">{{ faultType==='bias' ? '偏移量' : faultType==='stuck' ? '卡滞开度（0～100%）' : `冻结值（${device.unit}）` }}<input v-model.number="forcedValue" class="field" type="number" step="any"></label><label>异常内容 / 备注<input v-model="message" class="field" placeholder="留空使用原异常类型名称" maxlength="300"></label><div class="inject-footer"><span>本地注入会记录操作并产生告警；复位恢复可操作状态。</span><button class="btn btn-danger" type="button" @click="inject">注入异常</button></div></section></div></template><section v-else-if="activeTab === '自动触发设置'" class="auto-settings card"><h3>异常自动触发事件设置</h3><label v-for="item in autoSettingItems" :key="item.key" class="check-option"><input v-model="settingsDraft[item.key]" type="checkbox">{{ item.label }}</label><p>风机异常自动切换健康备用机；供应泵故障切换 / 全故障断流及水乙二醇自动控制使用同一中央配置。</p><div><button class="btn" type="button" @click="Object.assign(settingsDraft,Object.fromEntries(autoSettingItems.map(item => [item.key,state.settings[item.key]!==false])))">撤销编辑</button><button class="btn btn-primary" type="button" @click="saveAutoSettings">保存配置</button><button class="btn" type="button" @click="downloadJson('异常自动触发配置.json',clone(settingsDraft))">导出配置</button></div></section><section v-else><div class="fault-list-toolbar"><button class="btn" type="button" @click="exportFaults">导出 CSV</button><button class="btn btn-danger" type="button" :disabled="!activeFaults.length" @click="confirmation=true">复位全部异常</button></div><div v-if="confirmation" class="confirm-panel card"><strong>复位所有异常设备？动力设备会保持停止。</strong><button class="btn" type="button" @click="confirmation=false">取消</button><button class="btn btn-success" type="button" @click="resetAll">确认复位</button></div><ToolTable :rows="activeFaults" :columns="faultColumns" :page-size="10"><template #cell-value="{row}">{{ row.value.toFixed(2) }} {{ row.unit }}</template><template #cell-actions="{row}"><button class="btn row-button" type="button" @click="resetConfiguredFault(row.id)">复位</button></template></ToolTable></section></div>
</template>

<style scoped>
.fault-dialog {color:#46667c;}.fault-heading {display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:17px;}.fault-heading h3 {margin:0 0 7px;font-size:18px;color:#477798;}.fault-heading p {margin:0;font-size:11px;color:#93a8b7;}.fault-count {background:#fff1eb;color:#ba8067;}.fault-tabs {display:flex;gap:4px;border-bottom:1px solid #dce8f1;margin-bottom:17px;}.tab {border:0;border-bottom:2px solid transparent;background:none;color:#8ba4b7;padding:10px 15px;font:inherit;font-size:13px;cursor:pointer;}.tab.active {color:#397ea9;border-color:#397ea9;background:#f2f8fd;}.scenario-toolbar {display:flex;gap:7px;align-items:center;flex-wrap:wrap;padding:10px 12px;background:#f6f9fc;border:1px solid #e0e9f1;border-radius:8px;margin-bottom:15px;}.scenario-toolbar span {color:#8a9faf;font-size:10px;margin-right:6px;}.scenario-toolbar .btn {padding:6px 8px;font-size:10px;}.fault-layout {display:grid;grid-template-columns:minmax(235px,.85fr) minmax(350px,1.6fr);gap:18px;}.card {background:white;border:1px solid #dae7f1;border-radius:10px;box-shadow:none;}.device-list {overflow:hidden;}.list-search {padding:13px;display:flex;gap:7px;flex-direction:column;border-bottom:1px solid #e0eaf2;}.field {padding:8px 10px;font-size:12px;color:#50748d;border:1px solid #d8e4ed;border-radius:6px;background:white;width:100%;box-sizing:border-box;}.device-list-scroll {max-height:550px;overflow:auto;}.device-option {display:flex;gap:10px;align-items:center;justify-content:space-between;width:100%;padding:12px 14px;border:0;border-bottom:1px solid #edf2f6;background:white;cursor:pointer;color:#7690a4;text-align:left;}.device-option > div {display:flex;flex-direction:column;gap:4px;min-width:0;}.device-option strong {color:#507d9d;font-size:12px;}.device-option span {font-size:10px;line-height:1.5;}.device-option.selected {background:#eef7fd;border-left:3px solid #68a1c4;padding-left:11px;}.device-option.faulty .option-status {color:#c4866d;}.option-status {white-space:nowrap;color:#9fb1bf;}.list-count {display:block;padding:12px 14px;font-size:10px;color:#9badba;background:#f8fbfd;}.fault-editor {padding:18px;}.selected-device {display:flex;align-items:center;gap:20px;border-bottom:1px solid #e2ecf4;padding-bottom:15px;margin-bottom:14px;}.selected-device :deep(.device-visual) {height:90px;width:100px;min-height:90px;}.selected-device > div:last-child {flex:1;}.selected-device strong {font-size:14px;color:#2d7ba7;}.selected-device h4 {font-size:14px;margin:6px 0 8px;color:#68889e;}.selected-device p {font-size:12px;color:#839bab;margin:8px 0 0;}.editor-actions {display:flex;gap:6px;flex-wrap:wrap;}.editor-actions .btn {font-size:10px;padding:6px 8px;}.fault-editor > h4 {margin:22px 0 14px;font-size:14px;color:#5c7e97;}.fault-editor label {display:flex;flex-direction:column;gap:7px;font-size:12px;margin-top:13px;}.fault-description {font-size:11px;color:#99acba;line-height:1.8;margin:9px 0;}.check-option {display:flex !important;flex-direction:row !important;align-items:center;gap:8px !important;color:#7e99ac;font-size:12px;}.check-option input {width:16px;height:16px;accent-color:#4d91b7;}.sensor-override {margin-top:18px;padding:15px;background:#f3f9fc;border:1px solid #dcebf4;border-radius:8px;}.sensor-override h4 {margin:0;font-size:12px;}.override-row {display:flex;align-items:flex-end;gap:10px;}.override-row label {flex:1;}.override-row .btn {font-size:11px;white-space:nowrap;}.inject-footer {display:flex;gap:12px;align-items:center;justify-content:space-between;margin-top:18px;padding-top:15px;border-top:1px solid #e3edf4;}.inject-footer span {font-size:10px;color:#94a9b9;line-height:1.7;}.inject-footer .btn {white-space:nowrap;font-size:12px;}.auto-settings {padding:22px;}.auto-settings h3 {margin:0 0 20px;color:#527f9b;font-size:16px;}.auto-settings .check-option {padding:10px 0;}.auto-settings p {font-size:11px;line-height:1.9;color:#95a9b9;}.auto-settings > div {display:flex;gap:8px;margin-top:20px;}.auto-settings .btn {font-size:12px;}.fault-list-toolbar {display:flex;justify-content:flex-end;gap:8px;margin-bottom:14px;}.fault-list-toolbar .btn {font-size:11px;}.row-button {font-size:10px;padding:4px 8px;}.confirm-panel {padding:16px;display:flex;gap:10px;align-items:center;margin-bottom:15px;background:#fff9ef;border-color:#e6d6b4;font-size:12px;}.confirm-panel strong {margin-right:auto;color:#af8f5d;}
@media(max-width:720px){.fault-layout{grid-template-columns:1fr;}.device-list-scroll{max-height:180px;}.override-row{flex-wrap:wrap;}.override-row label{flex-basis:100%;}.confirm-panel{flex-wrap:wrap;}}
</style>
